// Contour helpers used only by the body-shape review configuration.
// The limb endpoints and original two-pixel cap overhang are retained.
function _bodyPreviewLimbPath(ctx, len, width) {
    ctx.beginPath(); ctx.moveTo(-len, 0);
    ctx.bezierCurveTo(-len, -width * 0.52, -len * 0.86, -width * 0.95, -len * 0.52, -width * 0.96);
    ctx.bezierCurveTo(-len * 0.16, -width * 0.99, len * 0.44, -width * 0.75, len * 0.80, -width * 0.53);
    ctx.bezierCurveTo(len * 0.97, -width * 0.39, len, -width * 0.15, len, 0);
    ctx.bezierCurveTo(len, width * 0.15, len * 0.97, width * 0.39, len * 0.80, width * 0.53);
    ctx.bezierCurveTo(len * 0.44, width * 0.75, -len * 0.16, width * 0.99, -len * 0.52, width * 0.96);
    ctx.bezierCurveTo(-len * 0.86, width * 0.95, -len, width * 0.52, -len, 0);
    ctx.closePath();
}
function _bodyPreviewFootPath(ctx, x, y) {
    // Ankle stays at x,y; heel projects 2.8px behind and toe 8.2px ahead.
    ctx.beginPath(); ctx.moveTo(x - 2.8, y - 1.55);
    ctx.bezierCurveTo(x - 2.8, y - 2.35, x - 1.9, y - 2.65, x - 0.3, y - 2.45);
    ctx.bezierCurveTo(x + 2.1, y - 2.4, x + 4.2, y - 2.65, x + 6.2, y - 2.65);
    ctx.bezierCurveTo(x + 8.9, y - 2.65, x + 8.9, y + 2.65, x + 6.2, y + 2.65);
    ctx.bezierCurveTo(x + 4.2, y + 2.65, x + 2.1, y + 2.4, x - 0.3, y + 2.45);
    ctx.bezierCurveTo(x - 1.9, y + 2.65, x - 2.8, y + 2.35, x - 2.8, y + 1.55);
    ctx.closePath();
}
function _bodyPreviewHandPath(ctx, x, y) {
    ctx.beginPath(); ctx.moveTo(x - 3.5, y);
    ctx.bezierCurveTo(x - 3.5, y - 1.8, x - 1.8, y - 2.5, x + 0.3, y - 2.5);
    ctx.bezierCurveTo(x + 2.6, y - 2.5, x + 3.55, y - 1.3, x + 3.55, y);
    ctx.bezierCurveTo(x + 3.55, y + 1.3, x + 2.6, y + 2.5, x + 0.3, y + 2.5);
    ctx.bezierCurveTo(x - 1.8, y + 2.5, x - 3.5, y + 1.8, x - 3.5, y);
    ctx.closePath();
}
function _bodyPreviewHipPath(ctx, x, width) {
    const end = x + width;
    ctx.beginPath(); ctx.moveTo(x + width * 0.38, -10.5);
    ctx.bezierCurveTo(x + width * 0.14, -10.5, x, -8.4, x, -5.3);
    ctx.bezierCurveTo(x, -1.8, x, 1.8, x, 5.3);
    ctx.bezierCurveTo(x, 8.4, x + width * 0.14, 10.5, x + width * 0.38, 10.5);
    ctx.bezierCurveTo(end - width * 0.2, 10.5, end, 8.9, end, 6.9);
    ctx.bezierCurveTo(end, 2.7, end, -2.7, end, -6.9);
    ctx.bezierCurveTo(end, -8.9, end - width * 0.2, -10.5, x + width * 0.38, -10.5);
    ctx.closePath();
}
function _bodyPreviewTorsoPath(ctx, x, width) {
    const end = x + width;
    ctx.beginPath(); ctx.moveTo(x, -5.5);
    ctx.bezierCurveTo(x, -7.5, x + width * 0.25, -7.6, x + width * 0.45, -8.2);
    ctx.bezierCurveTo(x + width * 0.72, -9.3, end - 0.3, -9.5, end, -6.2);
    ctx.bezierCurveTo(end + 0.2, -2.6, end + 0.2, 2.6, end, 6.2);
    ctx.bezierCurveTo(end - 0.3, 9.5, x + width * 0.72, 9.3, x + width * 0.45, 8.2);
    ctx.bezierCurveTo(x + width * 0.25, 7.6, x, 7.5, x, 5.5);
    ctx.bezierCurveTo(x + 0.45, 2.5, x + 0.45, -2.5, x, -5.5);
    ctx.closePath();
}

